import { SessionState } from '@reticlehq/core';
import { LOG_KIND, LOG_RESULT } from './presenter-log.js';
import { getCapabilities } from '../registry/capabilities.js';
/**
 * Compute the exported run-state from the controller's live fields: per-kind + pass/fail counts over
 * the activity log, the session duration, and the current capability surface. Extracted from
 * presenter.ts so the controller stays under the size cap; the counting is the same as before.
 */
export function buildRunState(input) {
    const start = input.startMs ?? input.now;
    const counts = { reads: 0, acts: 0, narrations: 0, human: 0, passes: 0, fails: 0 };
    for (const e of input.runLog) {
        if (e.kind === LOG_KIND.READ)
            counts.reads += 1;
        else if (e.kind === LOG_KIND.ACT)
            counts.acts += 1;
        else if (e.kind === LOG_KIND.NARRATION)
            counts.narrations += 1;
        else if (e.kind === LOG_KIND.HUMAN)
            counts.human += 1;
        if (e.result === LOG_RESULT.PASS)
            counts.passes += 1;
        else if (e.result === LOG_RESULT.FAIL)
            counts.fails += 1;
    }
    return {
        session: input.sessionId,
        url: 'undefined' === typeof location ? '' : location.href,
        state: input.state,
        startedMs: start,
        durationMs: Math.max(0, (input.endMs ?? input.now) - start),
        counts,
        capabilities: getCapabilities(),
        log: input.runLog.map((e) => ({ ...e })),
    };
}
